"use strict";

/**
 * Webhook triggers for routines: GitHub, Linear, Sentry, PagerDuty, or any
 * service that can sign a request.
 *
 * Each webhook routine has its own secret, generated by the server, shown to
 * the person once, and stored sealed with the vault (bound to the account and
 * the routine). Every delivery is verified the provider's own way against the
 * exact bytes received, before anything is parsed or stored:
 *
 *   github     X-Hub-Signature-256: sha256=<HMAC-SHA256(body)>
 *   linear     Linear-Signature: <HMAC-SHA256(body)>, webhookTimestamp within 5 minutes
 *   sentry     Sentry-Hook-Signature: <HMAC-SHA256(body)>
 *   pagerduty  X-PagerDuty-Signature: v1=<HMAC-SHA256(body)>[,v1=…] (key rotation)
 *   generic    X-HANNAH-Signature: sha256=<HMAC-SHA256("<timestamp>.<body>")>,
 *              X-HANNAH-Timestamp within 5 minutes (the format HANNAH's own webhooks use)
 *
 * A verified delivery fires the routine once per delivery id, within the
 * routine's teammate's usage limits and an hourly cap. The payload reaches the
 * teammate only as labelled, untrusted data in the task's brief: it can't
 * approve anything, change a rule or reach the vault.
 */
const crypto = require("node:crypto");
const express = require("express");
const { databaseConfigured, getDatabase } = require("../db");
const { decryptSecret, encryptSecret, vaultConfigured } = require("../vault");
const { clean, fail, parse, recordEvent, requireId, withAccount } = require("./common");

const PROVIDERS = ["github", "linear", "sentry", "pagerduty", "generic"];
const WINDOW_S = 5 * 60;
const HOURLY_CAP = 30;
const MAX_PAYLOAD_CHARS = 12_000;

const hmac = (secret, data) => crypto.createHmac("sha256", secret).update(data).digest("hex");
function same(a, b) {
  const left = Buffer.from(String(a || ""), "utf8");
  const right = Buffer.from(String(b || ""), "utf8");
  return left.length === right.length && left.length > 0 && crypto.timingSafeEqual(left, right);
}

/**
 * Verify one delivery. Returns { ok, event, delivery } or { ok: false }.
 * `headers` is lower-cased; `raw` is the exact request body.
 */
function verifyDelivery(provider, secret, headers, raw, body, nowS = Math.floor(Date.now() / 1000)) {
  const header = (name) => String(headers[name] || "");
  const digest = hmac(secret, raw);
  if (provider === "github") {
    if (!same(header("x-hub-signature-256"), `sha256=${digest}`)) return { ok: false };
    return { ok: true, event: `${header("x-github-event")}${body?.action ? `.${body.action}` : ""}`, delivery: header("x-github-delivery") };
  }
  if (provider === "linear") {
    if (!same(header("linear-signature"), digest)) return { ok: false };
    const at = Number(body?.webhookTimestamp);
    if (Number.isFinite(at) && Math.abs(nowS - Math.floor(at / 1000)) > WINDOW_S) return { ok: false };
    return { ok: true, event: `${body?.type || "event"}${body?.action ? `.${body.action}` : ""}`, delivery: header("linear-delivery") };
  }
  if (provider === "sentry") {
    if (!same(header("sentry-hook-signature"), digest)) return { ok: false };
    return { ok: true, event: `${header("sentry-hook-resource") || "event"}${body?.action ? `.${body.action}` : ""}`, delivery: header("request-id") };
  }
  if (provider === "pagerduty") {
    const offered = header("x-pagerduty-signature").split(",").map((item) => item.trim());
    if (!offered.some((item) => same(item, `v1=${digest}`))) return { ok: false };
    return { ok: true, event: String(body?.event?.event_type || "event"), delivery: String(body?.event?.id || "") };
  }
  if (provider === "generic") {
    const at = Number(header("x-hannah-timestamp"));
    if (!Number.isFinite(at) || Math.abs(nowS - at) > WINDOW_S) return { ok: false };
    if (!same(header("x-hannah-signature"), `sha256=${hmac(secret, `${at}.${raw}`)}`)) return { ok: false };
    return { ok: true, event: String(body?.event || header("x-hannah-event") || "event"), delivery: header("x-hannah-delivery") };
  }
  return { ok: false };
}

function matchesEvent(wanted, event) {
  if (!wanted) return true;
  return wanted.endsWith("*") ? event.startsWith(wanted.slice(0, -1)) : wanted === event;
}

/** A trimmed copy of the payload for the brief: data, capped, with no secrets in it from us. */
function payloadText(body) {
  const text = JSON.stringify(body ?? {}, null, 2);
  return text.length > MAX_PAYLOAD_CHARS ? `${text.slice(0, MAX_PAYLOAD_CHARS)}\n… (cut at ${MAX_PAYLOAD_CHARS} characters)` : text;
}

function publicBase() {
  return String(process.env.HANNAH_PUBLIC_URL || "").trim().replace(/\/+$/, "");
}

function webhookUrl(routineId) {
  return `${publicBase()}/api/hooks/routine/${routineId}`;
}

/** The trigger with its sealed secret, from a create or edit. Never returned to a caller. */
function sealSecret(userId, routineId, secret) {
  if (!vaultConfigured()) throw fail(503, "Webhook routines need the vault (HANNAH_VAULT_KEY) to keep their secret.", "vault-unconfigured");
  const sealed = encryptSecret(secret, { userId, providerId: `routine-hook:${routineId}` });
  return { keyId: sealed.keyId, wrappedKey: sealed.wrappedKey, ciphertext: sealed.ciphertext };
}

function openSecret(userId, routineId, sealed) {
  return decryptSecret({ keyId: sealed.keyId, wrappedKey: sealed.wrappedKey, ciphertext: sealed.ciphertext }, { userId, providerId: `routine-hook:${routineId}` }).secret;
}

function newSecret() {
  return `whsec_${crypto.randomBytes(24).toString("base64url")}`;
}

/** The webhook part of a routine as the person sees it. */
function publicWebhook(row) {
  const trigger = parse(row.trigger, {}) || {};
  if (row.mode !== "webhook") return null;
  return { url: webhookUrl(row.id), provider: trigger.provider, event: trigger.event || "", secretSet: Boolean(trigger.sealed) };
}

function createRoutineHooksRouter() {
  const router = express.Router();

  /** A new secret (the first, or a rotation). Shown once; the old one stops working at once. */
  router.post("/workforce/routines/:id/webhook-secret", express.json({ limit: "8kb" }), withAccount(async (req, res, db, account) => {
    if (account.via !== "session") throw fail(403, "Only a signed-in person can see a webhook secret.", "person-required");
    const row = (await db.query("SELECT * FROM hannah_routines WHERE user_id = $1 AND id = $2", [account.id, requireId(req.params.id, "routine")])).rows[0];
    if (!row) throw fail(404, "That routine doesn't exist.", "not-found");
    if (row.mode !== "webhook") throw fail(400, "Only a webhook routine has a secret.", "not-webhook");
    const secret = newSecret();
    const trigger = { ...(parse(row.trigger, {}) || {}), sealed: sealSecret(account.id, row.id, secret) };
    await db.query("UPDATE hannah_routines SET trigger = $1, updated_at = $2 WHERE user_id = $3 AND id = $4", [JSON.stringify(trigger), Date.now(), account.id, row.id]);
    await recordEvent(db, account.id, "routine.webhook_secret", { botId: row.bot_id, detail: { routineId: row.id, provider: trigger.provider } });
    res.json({ webhook: { url: webhookUrl(row.id), provider: trigger.provider, event: trigger.event || "", secretSet: true }, secret, note: "Copy the secret now; it isn't shown again." });
  }));

  return router;
}

/** The public delivery endpoint, mounted before the JSON parser: signatures cover the exact bytes. */
function createRoutineHookEndpoint() {
  const router = express.Router();
  const raw = express.raw({ type: "*/*", limit: "1mb" });
  router.post("/hooks/routine/:id", raw, async (req, res) => {
    try {
      if (!databaseConfigured() || !/^[A-Za-z0-9_-]{6,80}$/.test(String(req.params.id))) return res.status(404).json({ error: "Not found." });
      const db = await getDatabase();
      const row = (await db.query("SELECT * FROM hannah_routines WHERE id = $1 AND mode = 'webhook'", [String(req.params.id)])).rows[0];
      const trigger = parse(row?.trigger, {}) || {};
      if (!row || !trigger.sealed) return res.status(404).json({ error: "Not found." });
      const buffer = Buffer.isBuffer(req.body) ? req.body : Buffer.alloc(0);
      let body = {};
      try { body = buffer.length ? JSON.parse(buffer.toString("utf8")) : {}; } catch { body = null; }
      let secret;
      try { secret = openSecret(row.user_id, row.id, trigger.sealed); } catch { return res.status(503).json({ error: "This routine's secret can't be read on this server." }); }
      const headers = Object.fromEntries(Object.entries(req.headers).map(([key, value]) => [key.toLowerCase(), Array.isArray(value) ? value[0] : value]));
      const verdict = verifyDelivery(trigger.provider, secret, headers, buffer.toString("utf8"), body || {});
      if (!verdict.ok) return res.status(401).json({ error: "Not authorized." });
      if (body === null) return res.status(400).json({ error: "Expected JSON." });
      // A provider's ping/test delivery proves the connection; it doesn't run the routine.
      if (/^(ping|test|installation\.)/.test(verdict.event)) return res.status(200).json({ ok: true, ignored: "ping" });
      if (row.status !== "active") return res.status(202).json({ ok: true, ignored: "paused" });
      if (!matchesEvent(trigger.event, verdict.event)) return res.status(202).json({ ok: true, ignored: "event-filtered" });
      const delivery = clean(verdict.delivery, 120) || crypto.createHash("sha256").update(buffer).digest("hex").slice(0, 32);
      const label = clean(`webhook:${trigger.provider}:${verdict.event}#${delivery}`, 300);
      const seen = await db.query("SELECT id FROM hannah_routine_runs WHERE user_id = $1 AND routine_id = $2 AND trigger = $3", [row.user_id, row.id, label]);
      if (seen.rows[0]) return res.status(200).json({ ok: true, duplicate: true, runId: seen.rows[0].id });
      const hour = await db.query("SELECT COUNT(*) AS count FROM hannah_routine_runs WHERE user_id = $1 AND routine_id = $2 AND created_at > $3 AND trigger LIKE 'webhook:%'", [row.user_id, row.id, Date.now() - 60 * 60_000]);
      if (Number(hour.rows[0]?.count || 0) >= HOURLY_CAP) return res.status(429).json({ error: `This routine took ${HOURLY_CAP} webhook runs in the last hour.` });
      const { fireRoutine } = require("./routines");
      const run = await fireRoutine(db, row, {
        trigger: label, plannedFor: Date.now(), eventId: delivery,
        payload: { provider: trigger.provider, event: verdict.event, delivery, text: payloadText(body) },
      });
      if (!run) return res.status(409).json({ error: "The routine's skill is missing; it was paused." });
      if (run.limited) return res.status(429).json({ error: run.error });
      res.status(202).json({ ok: true, runId: run.runId, taskId: run.taskId });
    } catch (error) {
      console.error(`Routine webhook failed (${error?.code || error?.name || "error"}).`);
      if (!res.headersSent) res.status(500).json({ error: "The delivery couldn't be handled." });
    }
  });
  return router;
}

module.exports = { HOURLY_CAP, PROVIDERS, createRoutineHookEndpoint, createRoutineHooksRouter, matchesEvent, newSecret, publicWebhook, sealSecret, verifyDelivery, webhookUrl };
